"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["81893"],{78490(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.regra_de_modalidade_cita_fato_nao_coletado","status":422,"titulo":"A regra de aplicabilidade de uma modalidade ofertada cita um fato que o processo n\xe3o coleta nem deriva"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.regra_de_modalidade_cita_fato_nao_coletado","requisitos":[],"oQueAconteceu":["Cada modalidade ofertada no processo tem uma regra que decide quem concorre a\\nela. Em processo com inscri\xe7\xe3o pr\xf3pria, a modalidade \xe9 decidida na inscri\xe7\xe3o; por\\nisso a regra s\xf3 pode depender de fatos que o formul\xe1rio de inscri\xe7\xe3o pergunta\\nou que o processo calcula a partir dessas respostas. A regra de uma modalidade\\nofertada cita um fato que a inscri\xe7\xe3o n\xe3o pergunta, nem direta nem\\nindiretamente, e o sistema ficaria sem saber se o candidato concorre a ela.","Tr\xeas pontos sobre a confer\xeancia:","- um fato calculado vale se tudo de que ele depende vem da inscri\xe7\xe3o; a mensagem pode citar um fato do qual a regra depende por interm\xe9dio de outro;\\n- um campo de grupo repet\xedvel n\xe3o vale citado sozinho: s\xf3 vale por meio de um resumo do grupo, desde que algum grupo do formul\xe1rio de inscri\xe7\xe3o pergunte o campo;\\n- em processo cujo resultado \xe9 importado, a modalidade vem com o candidato e a regra n\xe3o \xe9 avaliada, e por isso n\xe3o h\xe1 esta recusa.","A recusa acontece ao tentar congelar uma vers\xe3o (publica\xe7\xe3o inicial ou retifica\xe7\xe3o em ato \xfanico), e nada \xe9 congelado.\\nA mensagem indica a modalidade e o fato que falta."],"comoResolver":["Escolha uma das sa\xeddas, conforme o caso:","- inclua o fato apontado entre os que o formul\xe1rio de inscri\xe7\xe3o pergunta;\\n- crie uma deriva\xe7\xe3o que calcule o fato a partir de fatos que a inscri\xe7\xe3o\\n  pergunta;\\n- retire da distribui\xe7\xe3o de vagas a modalidade cuja regra n\xe3o pode ser avaliada\\n  na inscri\xe7\xe3o;\\n- se a regra da modalidade no cadastro est\xe1 errada, pe\xe7a a corre\xe7\xe3o a quem\\n  mant\xe9m o cadastro de modalidades e grave de novo a distribui\xe7\xe3o de vagas do\\n  processo, para que ela copie a regra corrigida.","Em processo j\xe1 publicado, as altera\xe7\xf5es s\xe3o feitas numa retifica\xe7\xe3o. Depois,\\nrepita a opera\xe7\xe3o recusada."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);